window.MOTIF_CATALOG_CHUNKS[78]={"cards":[{"id":"MEJE-KW-005590","row_version":1,"title":"사랑 고백 직후 이어지는 성관계","original":"Confession Triggers Consummation","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"처음 사랑을 고백한 인물들이 곧바로 성관계를 맺는 전개. 감정 확인과 신체적 관계의 전환을 한 장면에 붙인다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005590/index.html"},{"id":"MEJE-KW-005591","row_version":1,"title":"더 작은 잘못을 대신 인정하기","original":"Confess to a Lesser Crime","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"큰 비밀이 들킬 것 같자 인물이 상대가 받아들일 만한 작은 잘못을 고백한다. 부분적인 진실이 더 중요한 사실을 숨기는 방패가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005591/index.html"},{"id":"MEJE-KW-005592","row_version":1,"title":"우승자를 덮는 색종이","original":"Confetti Drop","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"공개 무대의 큰 승리 뒤에 색종이와 풍선이 쏟아져 축하를 눈에 보이게 한다. 과한 장식이 당사자의 놀람까지 웃음으로 바꿀 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005592/index.html"},{"id":"MEJE-KW-005593","row_version":2,"title":"자신감을 심어 주려 꾸민 사건","original":"Confidence-Building Scheme","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"주변 사람이 인물의 자신감을 회복시키려고 성공 경험을 몰래 마련한다. 선의의 조작이 들키면 성취의 진실성이 다시 문제 된다. 자신감을 높이려고 몰래 꾸민 사건과 실패로 믿게 만드는 몰래 방해는 진실을 숨긴 개입이라는 점에서 반대 방향으로 작동한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005593/index.html"},{"id":"MEJE-KW-005594","row_version":1,"title":"실패로 믿게 만드는 몰래 방해","original":"Confidence Sabotage","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"누군가가 유능한 인물의 일을 은밀히 망쳐 그가 자기 실력을 의심하게 만든다. 실패 원인을 알게 되는 순간 잃은 자신감을 되찾을 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-005594/index.html"},{"id":"MEJE-KW-005595","row_version":1,"title":"맡긴 비밀을 퍼뜨리기","original":"Confidentiality Betrayal","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"사적으로 털어놓은 이야기가 듣는 사람의 입을 거쳐 다른 이에게 전해진다. 공유한 정보의 범위가 신뢰의 경계를 무너뜨린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005595/index.html"},{"id":"MEJE-KW-005596","row_version":1,"title":"방어벽이 안쪽을 감옥으로 만들기","original":"Confining Defenses","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"위협을 막으려고 만든 장벽이나 대피처가 오히려 인물을 안에 가둔다. 안전을 위해 포기한 출구가 새로운 위험이 된다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-005596/index.html"},{"id":"MEJE-KW-005598","row_version":1,"title":"확인하고 나서 사실 밝히기","original":"Confirm Before Reveal","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"중요한 것을 본 인물이 곧장 말하지 않고 주변인에게 몇 가지를 물어 사실을 확인한다. 공개가 지연되는 동안 관객은 그가 무엇을 발견했는지 기다린다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005598/index.html"},{"id":"MEJE-KW-005599","row_version":1,"title":"결혼을 완강히 거부하는 독신자","original":"Confirmed Bachelor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 단순히 미혼인 수준을 넘어 자신은 결혼하지 않겠다고 분명히 정한다. 주변의 혼인 기대와 개인의 선택이 충돌한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005599/index.html"},{"id":"MEJE-KW-005600","row_version":1,"title":"급한 사람이 남의 전화를 가져다 쓰기","original":"Confiscated Phone","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"누군가가 긴급한 연락을 위해 다른 사람이 쓰던 전화를 빼앗거나 잠시 가져간다. 연락의 시급함과 소유자의 권리가 짧은 장면에서 부딪친다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005600/index.html"},{"id":"MEJE-KW-005601","row_version":5,"title":"이야기를 움직이는 갈등","original":"Conflict","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 원하는 것과 그를 가로막는 힘이 부딪쳐 이야기가 진행된다. 장애는 다른 사람일 수도 있고 상황이나 인물의 내면일 수도 있다. 이야기를 움직일 충돌이 필요하다는 이유로 성격에 맞지 않는 다툼을 넣으면 이유 없이 충돌을 일으키는 인물이 된다. 가족과 국가의 요구가 부딪히는 서로 충돌하는 충성심는 인물 내면에 생긴 갈등이다. 기존의 두 세력이 새 위협에 맞서게 되면 공통의 적 때문에 끝나는 다툼가 원래 갈등을 밀어낸다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005601/index.html"},{"id":"MEJE-KW-005602","row_version":2,"title":"이유 없이 충돌을 일으키는 인물","original":"Conflict Ball","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"이전의 태도와 맞지 않는데도 인물이 갑자기 반대하거나 다투며 사건을 억지로 만든다. 갈등을 만들려는 이야기의 필요가 성격의 일관성을 깨뜨린다. 인물이 이전과 다른 이유 없는 다툼을 만들면 서사의 일관성도 흔들릴 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-005602/index.html"},{"id":"MEJE-KW-005603","row_version":1,"title":"서로 충돌하는 충성심","original":"Conflicting Loyalty","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 가족과 국가, 친구처럼 둘 이상을 지켜야 해 어느 쪽을 택해도 다른 약속을 어긴다. 옳은 마음들이 동시에 성립하지 않는 선택의 고통이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-005603/index.html"},{"id":"MEJE-KW-005604","row_version":1,"title":"공통의 적 때문에 끝나는 다툼","original":"Conflict Killer","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"서로 싸우던 두 편 앞에 모두를 위협하는 제삼자가 나타나 원래의 분쟁이 뒤로 밀린다. 새 위협이 화해와 협력의 이유가 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-005604/index.html"},{"id":"MEJE-KW-005605","row_version":1,"title":"다 함께 반응하느라 성격이 바뀌기","original":"Conforming OOC Moment","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"단체 장면에서 평소와 맞지 않는 인물까지 똑같이 웃거나 놀란다. 집단 반응을 만드는 편의가 개별 인물의 성격을 잠시 지운다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005605/index.html"},{"id":"MEJE-KW-005606","row_version":2,"title":"적의를 감춘 과도한 친절","original":"Confound Them with Kindness","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 상대를 혼란스럽게 하거나 경계를 풀게 하려고 예상 밖의 예의를 보인다. 친절의 겉모습과 실제 의도가 다르다. 친절을 가장해 상대를 흔드는 인물은 공손하게 깔보는 침착함으로 그 의도를 감출 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005606/index.html"},{"id":"MEJE-KW-005607","row_version":1,"title":"진짜 인물 앞에 나타난 사칭자","original":"Confronting Your Imposter","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"누군가를 흉내 내던 인물이 바로 그 본인과 마주친다. 둘이 동시에 존재하는 순간 거짓 신분을 유지하기 어려워진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005607/index.html"},{"id":"MEJE-KW-005608","row_version":1,"title":"공자 말을 멋대로 인용하는 고정관념","original":"Confucian Confusion","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"중국인 인물을 등장시키며 실제 출처가 불분명한 말을 공자의 가르침으로 소개한다. 문화의 복잡함을 우스운 한마디로 줄이는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005608/index.html"},{"id":"MEJE-KW-005609","row_version":1,"title":"사건을 헷갈려 하는 목격자 인터뷰","original":"Confused Bystander Interview","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"큰 사건 뒤 기자가 현장의 목격자를 만나지만 증언은 과장되거나 엉뚱한 곳으로 샌다. 공적인 보도와 개인의 기억 사이의 간극이 드러난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005609/index.html"},{"id":"MEJE-KW-005610","row_version":1,"title":"혼란을 나타내는 물음표","original":"Confused Question Mark","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물 머리 위나 말풍선에 물음표가 나타나 이해하지 못한 상태를 보여 준다. 추상적 감정을 짧은 그림 기호로 전달한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005610/index.html"},{"id":"MEJE-KW-005611","row_version":1,"title":"부정이 겹쳐 뜻을 흐리는 말","original":"Confusing Multiple Negatives","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 부정 표현을 여러 겹 쌓아 결국 찬성인지 반대인지 알기 어렵게 만든다. 복잡한 문장 자체가 혼란이나 회피의 도구가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005611/index.html"},{"id":"MEJE-KW-005612","row_version":1,"title":"예측할 수 없는 몸놀림으로 싸우기","original":"Confusion Fu","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대가 다음 움직임을 읽지 못하도록 인물이 낯설고 변칙적인 동작을 보인다. 겉보기의 무질서가 전투에서 이점이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005612/index.html"},{"id":"MEJE-KW-005613","row_version":1,"title":"코 막힌 소리를 글자로 표현하기","original":"Congestion Speak","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물의 코가 막혀 달라진 발음을 글의 자음 변화로 나타낸다. 상태를 설명하지 않고도 대사의 소리로 알아채게 한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005613/index.html"},{"id":"MEJE-KW-005614","row_version":3,"title":"같은 상황에서 떠오르는 기억","original":"Congruent Memory","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"작품에서 인물이 무언가를 배웠던 장소나 감정 상태로 돌아가자 잊었던 내용을 떠올린다. 실제 기억 현상을 서사에서 극적으로 확대해 쓰는 경우가 많다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-005614/index.html"},{"id":"MEJE-KW-005615","row_version":2,"title":"붙어 있는 만화 눈","original":"Conjoined Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"만화 인물의 두 눈 흰자위가 중앙에서 이어져 하나의 큰 눈처럼 보인다. 해부학보다 알아보기 쉬운 표정과 실루엣을 택한 디자인이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-005615/index.html"},{"id":"MEJE-KW-005616","row_version":1,"title":"결합 쌍둥이의 재현","original":"Conjoined Twins","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"몸의 일부를 공유하는 쌍둥이가 작품의 인물로 등장한다. 공포나 구경거리로만 다루는 관습과 각자의 삶과 선택을 보여 주는 표현을 구분한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005616/index.html"},{"id":"MEJE-KW-005617","row_version":1,"title":"‘하지만’에서 끊기는 변명","original":"Conjunction Interruption","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 이유를 설명하려고 접속사를 꺼내자 권위자가 말을 가로막는다. 말할 기회 자체를 주지 않는 관계의 힘을 짧은 대사로 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005617/index.html"},{"id":"MEJE-KW-005618","row_version":1,"title":"창작 언어","original":"Conlang","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품의 세계와 종족을 위해 새로 만든 말과 문법 체계. 단어 몇 개를 넘어 언어의 규칙이 그 사회의 사고방식을 드러낼 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005618/index.html"},{"id":"MEJE-KW-005619","row_version":2,"title":"신뢰를 이용하는 사기꾼","original":"Con Man","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 상대의 믿음을 얻어 돈이나 원하는 것을 빼앗는다. 친절한 첫인상과 숨은 계산이 한 인물 안에 공존한다. 신뢰와 말솜씨를 무기로 삼는 인물은 총을 꺼리는 사기꾼처럼 총에 의존하는 상황을 꺼릴 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005619/index.html"},{"id":"MEJE-KW-005620","row_version":2,"title":"총을 꺼리는 사기꾼","original":"Con Men Hate Guns","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"말과 속임수로 문제를 푸는 인물이 무장한 충돌을 피하려 한다. 폭력이 시작되는 순간 자신이 잘하는 규칙에서 벗어난다는 계산이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005620/index.html"},{"id":"MEJE-KW-005621","row_version":1,"title":"사실 오래전부터 연결된 인물들","original":"Connected All Along","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"서로 무관해 보이던 조연들이 과거에 만났거나 같은 사건에 얽혀 있었음이 드러난다. 이미 본 관계망을 새롭게 읽게 하는 반전이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005621/index.html"},{"id":"MEJE-KW-005622","row_version":1,"title":"인맥이 힘이 되지 않는 순간","original":"Connections Are Not Power","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"높은 사람을 안다는 협박이 상대에게 통하지 않거나 그 연줄이 이미 쓸모없어진다. 빌려 온 권력의 허약함이 드러난다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-005622/index.html"},{"id":"MEJE-KW-005623","row_version":1,"title":"사건 장소들을 이으면 나타나는 그림","original":"Connect the Deaths","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"서로 다른 죽음이나 이상 현상의 위치를 지도에 표시하자 숨은 모양이 나타난다. 흩어진 사건을 하나의 의도로 읽는 추리 장치다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-005623/index.html"},{"id":"MEJE-KW-005624","row_version":2,"title":"정복자로 자란 외계 왕자","original":"Conquering Alien Prince","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"외계에서 온 왕자나 강한 후계자가 새로운 행성을 지배할 권리와 임무를 배운다. 귀족의 지위와 침략자의 역할이 합쳐진 인물이다. 침략자의 우월한 지위를 앞세우는 인물 유형은 미래 기술로 과거를 정복하려는 자처럼 미래 기술을 권력의 근거로 삼기도 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005624/index.html"},{"id":"MEJE-KW-005625","row_version":1,"title":"미래 기술로 과거를 정복하려는 자","original":"Conqueror from the Future","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"미래에서 온 인물이 앞선 기술을 이용해 과거의 사회를 지배하려 한다. 시간의 격차를 군사적 우위로 바꾸는 침략 구도다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005625/index.html"},{"id":"MEJE-KW-005626","row_version":2,"title":"팬 행사 방문기를 그린 만화","original":"Con Recap","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"웹만화 작가가 팬 행사에 다녀온 경험을 본편이나 별도 만화로 정리한다. 창작자의 실제 활동이 작품의 연재 일정과 내용에 들어온다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005626/index.html"},{"id":"MEJE-KW-005627","row_version":2,"title":"양심 때문에 되돌아가 돕기","original":"Conscience Makes You Go Back","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"떠나던 인물이 자신이 외면한 사람을 생각하고 발걸음을 돌린다. 행동을 바꾸는 짧은 순간이 인물의 도덕적 선택을 보여 준다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005627/index.html"},{"id":"MEJE-KW-005628","row_version":2,"title":"사회 문제를 다루는 힙합","original":"Conscious Hip Hop","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"가사가 불평등과 공동체의 삶, 사회적 갈등을 중심에 두는 힙합의 흐름. 개인의 경험을 더 넓은 현실과 연결한다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-005628/index.html"},{"id":"MEJE-KW-005629","row_version":1,"title":"몸을 빼앗겼지만 의식은 남기","original":"Conscious While Possessed","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"다른 존재가 몸을 움직이는 동안에도 원래 인물은 안에서 상황을 지켜본다. 알면서도 행동하지 못하는 상태가 공포와 저항의 가능성을 함께 만든다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005629/index.html"},{"id":"MEJE-KW-005630","row_version":2,"title":"강제 동원","original":"Conscription","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"국가가 법이나 권력으로 사람들을 군대 또는 공적 복무에 끌어들인다. 개인의 뜻과 공동체의 필요가 충돌하는 제도다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005630/index.html"},{"id":"MEJE-KW-005631","row_version":2,"title":"스스로 공연을 택하는 동물","original":"Consenting Animal Performers","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"동물이 사람의 강요를 받지 않고 공연에 참여하거나 직접 무대를 꾸민다. 동물에게 의사와 선택권이 있는 세계관이 공연의 의미를 바꾼다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-005631/index.html"},{"id":"MEJE-KW-005632","row_version":1,"title":"보상과 벌을 함께 내미는 제안","original":"Consequence Combo","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"한 사람이 임무를 받아들이면 보상을 주고 거절하면 불이익을 주겠다고 말한다. 선택처럼 보이는 요청이 사실상 압박이 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-005632/index.html"},{"id":"MEJE-KW-005633","row_version":3,"title":"유능함이 팀 안에서 상쇄되기","original":"Conservation of Competence","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"한편의 우두머리가 뛰어나면 부하가 서툴고, 부하가 똑똑하면 우두머리가 실수하는 식으로 균형을 맞춘다. 전체 집단의 위협을 일정하게 유지하는 서사 관습이다. 집단의 유능함을 나누어 균형을 맞추는 방식은 적의 수가 늘수록 약해지는 적의 수가 늘수록 개인은 약해지기와 닮았다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005633/index.html"},{"id":"MEJE-KW-005634","row_version":2,"title":"적의 수가 늘수록 개인은 약해지기","original":"Conservation of Ninjutsu","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"홀로 나오면 강한 적이 무리로 등장하면 쉽게 쓰러진다. 전투의 규모를 키우면서 주인공의 생존 가능성을 남기는 연출이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005634/index.html"},{"id":"MEJE-KW-005635","row_version":1,"title":"보수적인 아버지와 진보적인 어머니","original":"Conservative Dad, Liberal Mom","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족 이야기에서 부모의 정치적·사회적 태도를 정반대로 배치한다. 한 가정 안의 의견 차이를 반복적인 갈등과 대화의 원천으로 쓴다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005635/index.html"},{"id":"MEJE-KW-005636","row_version":2,"title":"서사의 일관성","original":"Consistency","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"작품이 현실의 사실, 장르 관습, 작품 내부의 설정과 인물 행동 중 어떤 기준을 따르는지에 따라 앞뒤가 납득되게 맞물리는 정도. 내부 규칙뿐 아니라 외부 기준과의 관계도 살핀다. 인물이 단체 반응에 끼느라 평소 성격을 잊는 다 함께 반응하느라 성격이 바뀌기은 성격의 일관성을 깨는 사례다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005636/index.html"},{"id":"MEJE-KW-005637","row_version":1,"title":"바뀌는 옷에도 남는 자기 스타일","original":"Consistent Clothing Style","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 매번 다른 옷을 입어도 비슷한 색과 형태, 분위기를 꾸준히 고른다. 옷장의 다양함 속에서도 인물의 취향이 반복된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-005637/index.html"},{"id":"MEJE-KW-005638","row_version":2,"title":"낮게 평가된 작품에 돌아간 뒤늦은 상","original":"Consolation Award","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"오랫동안 수상에서 외면받은 창작자가 비교적 낮은 평가를 받은 후속 작업으로 상을 받는다. 특정 작품의 성취보다 경력 전체를 뒤늦게 인정했다는 해석이 생긴다. 오랜 공로를 뒤늦게 인정하는 상은 경연에서 우승하지 못한 사람에게 주는 작은 선물과 구분된다: 우승하지 못한 사람의 위로상.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005638/index.html"},{"id":"MEJE-KW-005639","row_version":1,"title":"위로하려다 더 나빠지는 이야기","original":"Consolation Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"불행을 겪은 사람에게 아직 남은 좋은 것을 짚어 주지만 그마저 곧 사라지거나 이미 잃었다는 사실이 드러난다. 선의의 위로가 불운의 목록을 늘리는 농담이 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005639/index.html"},{"id":"MEJE-KW-005640","row_version":2,"title":"우승하지 못한 사람의 위로상","original":"Consolation Prize","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"승자가 아닌 참가자에게도 작은 상품을 건네 실망을 덜어 준다. 본상과의 격차가 위안이나 우스운 역설을 만든다. 원한 우승은 놓쳤지만 전혀 다른 성취를 얻는 전개도 위로의 방향을 바꾼다: 실패하다 다른 기록을 세우기.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005640/index.html"},{"id":"MEJE-KW-005641","row_version":1,"title":"실패하다 다른 기록을 세우기","original":"Consolation World Record","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"목표한 세계 기록에는 실패했지만 그 과정에서 뜻밖의 다른 기록을 세운다. 실패의 결과가 예상 밖의 성취로 다시 읽힌다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005641/index.html"},{"id":"MEJE-KW-005642","row_version":1,"title":"게임 속에 등장한 실제 콘솔","original":"Console Cameo","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"플레이 중인 게임에 그 게임을 구동하는 기기나 같은 회사의 콘솔이 소품으로 나타난다. 현실의 플레이 도구가 작품 속 세계와 짧게 만난다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005642/index.html"},{"id":"MEJE-KW-005643","row_version":2,"title":"과시적 소비","original":"Conspicuous Consumption","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"필요를 채우는 것보다 부와 지위를 남에게 보여 주기 위해 큰돈을 쓴다. 소유한 물건이 인물의 사회적 위치를 알리는 공연처럼 쓰인다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005643/index.html"},{"id":"MEJE-KW-005644","row_version":1,"title":"눈에 띄는 전기 장애물","original":"Conspicuous Electric Obstacle","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 공간에 전기가 흐르는 듯한 위험 지형을 뚜렷하게 배치한다. 빛과 소리가 접근할 수 없는 곳을 알려 이동의 리듬을 바꾼다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005644/index.html"},{"id":"MEJE-KW-005645","row_version":1,"title":"이유 없이 눈에 띄는 장갑","original":"Conspicuous Gloves","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"직업, 추위, 사회 관습 같은 실용적 이유가 없어 보이는데도 인물이 한쪽 또는 양쪽 장갑을 계속 낀다. 정체나 비밀을 암시하는 외형 단서가 된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005645/index.html"},{"id":"MEJE-KW-005646","row_version":1,"title":"군중과 반대로 행동해 눈에 띄기","original":"Conspicuous in the Crowd","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"모두가 도망치거나 멈춰 있을 때 한 사람만 다른 속도로 움직인다. 대사를 듣기 전부터 관객의 시선이 그 인물에게 향한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005646/index.html"},{"id":"MEJE-KW-005647","row_version":1,"title":"배경에서 혼자 밝게 그려진 물건","original":"Conspicuously Light Patch","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"움직일 물건만 주변 배경보다 밝거나 선명하게 그려진 애니메이션 화면이다. 제작 방식의 차이가 다음 행동을 미리 알아보게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005647/index.html"},{"id":"MEJE-KW-005648","row_version":1,"title":"사람들 앞에서 벌어지는 암살","original":"Conspicuously Public Assassination","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"숨겨야 할 것 같은 살인이 공개된 장소에서 벌어져 주변에 공포와 혼란을 퍼뜨린다. 목격자가 많다는 사실이 오히려 권력의 과시가 되기도 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005648/index.html"},{"id":"MEJE-KW-005649","row_version":2,"title":"선택적으로만 눈치채는 경비원","original":"Conspicuously Selective Perception","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"잠입 게임의 경비원이 플레이어의 작은 행동에는 민감하면서 주변의 큰 변화에는 반응하지 않는다. 현실적인 감시보다 게임의 탐색 규칙이 앞선다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005649/index.html"},{"id":"MEJE-KW-005650","row_version":2,"title":"숨기려는데 더 눈에 띄는 트렌치코트","original":"Conspicuous Trenchcoat","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 모자와 긴 외투로 정체를 감추려 하지만 그 차림 자체가 수상함을 알린다. 숨김과 눈에 띔의 모순이 외형의 재미가 된다. 정체를 감춰야 할 사람이 겉모습으로 눈에 띄듯 비밀 조직도 표식으로 자신을 드러낼 수 있다: 곳곳에 드러난 비밀 조직의 표식.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005650/index.html"},{"id":"MEJE-KW-005651","row_version":3,"title":"모든 음모론이 뒤엉킨 세계","original":"Conspiracy Kitchen Sink","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"서로 어긋날 법한 음모론들이 한 세계에서 모두 사실처럼 성립한다. 비밀이 겹칠수록 배후의 질서는 오히려 더 혼란스러워진다. 여러 비밀 계획이 겹친 세계는 한 사람이 거대한 배후를 좇는 스릴러의 무대가 된다: 거대한 음모를 파헤치는 스릴러.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005651/index.html"},{"id":"MEJE-KW-005652","row_version":2,"title":"곳곳에 드러난 비밀 조직의 표식","original":"Conspiracy Placement","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"숨어 활동해야 할 조직의 상징이 여러 장소와 물건에 지나치게 자주 보인다. 은밀함과 노골적인 자기 홍보 사이의 모순이 드러난다. 수많은 표식이 모두 다른 비밀 조직을 가리킨다면 세계의 음모는 더 복잡해진다: 모든 음모론이 뒤엉킨 세계.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005652/index.html"},{"id":"MEJE-KW-005653","row_version":4,"title":"부패를 걷어 낸 비밀 조직과 다시 손잡기","original":"Conspiracy Redemption","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"영웅을 이용하던 조직의 일부 권력자가 드러나고 물러난 뒤 남은 구성원들이 영웅과 관계를 회복한다. 조직 전체의 목적과 내부 부패를 분리하는 결말이다. 조직의 진의를 의심하고 내부의 부패를 밝히는 과정은 음모 스릴러의 갈등과 맞닿는다: 거대한 음모를 파헤치는 스릴러.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005653/index.html"},{"id":"MEJE-KW-005654","row_version":2,"title":"어디서나 음모를 의심하는 인물","original":"Conspiracy Theorist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 우연이나 불확실한 사건에서도 숨은 계획을 찾아내려 한다. 그 의심이 근거 있는 경계인지 과도한 확신인지는 이야기마다 다르다. 숨은 계획에 대한 의심이 실제 사건과 맞아떨어지면 추적하는 이야기로 이어질 수 있다: 거대한 음모를 파헤치는 스릴러.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005654/index.html"},{"id":"MEJE-KW-005655","row_version":1,"title":"거대한 음모를 파헤치는 스릴러","original":"Conspiracy Thriller","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"작은 사건의 이상한 점을 추적하던 인물이 권력층까지 이어지는 비밀 계획을 발견한다. 믿을 사람이 줄어들수록 추적의 긴장이 커진다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-005655/index.html"},{"id":"MEJE-KW-005656","row_version":2,"title":"흔들리지 않는 기준으로서의 북극성","original":"Constant as the Northern Star","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"북극성을 방향과 변치 않는 약속의 상징으로 쓴다. 하늘의 한 점이 인물에게 길잡이나 지켜야 할 기준이 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-005656/index.html"},{"id":"MEJE-KW-005657","row_version":1,"title":"계속 바뀌는 이름","original":"Constantly Changing Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물, 장소 또는 사물의 이름이 여러 차례 바뀌어 주변 사람을 헷갈리게 한다. 변화 자체가 과거의 은폐나 새로운 정체를 드러낼 수 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005657/index.html"},{"id":"MEJE-KW-005658","row_version":1,"title":"무엇이든 묻는 호기심 많은 인물","original":"Constantly Curious","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 만나는 사람과 사물에 끊임없이 질문을 던진다. 순진한 물음이 다른 이들이 당연히 여긴 규칙의 빈틈을 드러낸다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005658/index.html"},{"id":"MEJE-KW-005659","row_version":1,"title":"언제나 우유가 나오는 소","original":"Constantly Lactating Cow","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"이야기 속 젖소가 번식과 돌봄의 과정과 무관하게 늘 우유를 제공한다. 축산의 시간을 지운 채 필요한 자원을 곧바로 얻는 세계의 편의가 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005659/index.html"},{"id":"MEJE-KW-005660","row_version":2,"title":"만날 때마다 이름 철자를 알려 주기","original":"Constantly Spells Their Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 자기소개할 때마다 이름의 글자를 하나씩 말한다. 처음에는 설명이지만 반복되면 그 사람만의 말버릇이 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005660/index.html"},{"id":"MEJE-KW-005661","row_version":1,"title":"별자리를 실제 우주 지역으로 다루기","original":"Constellations as Locations","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"지구에서 보이는 별자리 무늬를 멀리 떨어진 우주에서도 하나의 가까운 별 무리처럼 취급한다. 관측 시점에 따라 바뀌는 하늘의 그림을 실제 지리로 바꾸는 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005661/index.html"},{"id":"MEJE-KW-005662","row_version":1,"title":"제약을 걸고 쓰는 글","original":"Constrained Writing","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작가가 특정 글자나 문장 형식을 제한하는 규칙을 세우고 글을 쓴다. 제한이 표현의 선택을 좁히는 동시에 새로운 해결책을 이끈다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005662/index.html"},{"id":"MEJE-KW-005663","row_version":4,"title":"전장 한복판에서 기지를 짓는 게임","original":"Construct Additional Pylons","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"실시간 전략 게임에서 플레이어가 전투가 진행되는 동안 생산 시설과 기지를 세운다. 병력 지휘와 자원 운영이 같은 시간에 맞물린다. 전장 안에서 시설을 세우고 자원을 운영하는 규칙은 더 넓은 건설·운영 장르와 겹친다: 건설·운영 게임.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005663/index.html"},{"id":"MEJE-KW-005664","row_version":1,"title":"현실과 연결되지 않은 창작 세계","original":"Constructed World","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"현실의 지구를 미래나 과거로 바꾼 배경이 아니라 처음부터 별개의 장소와 역사를 설계한 세계다. 그 안의 인물은 현실과의 연결 없이도 자기 사회의 삶을 산다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005664/index.html"},{"id":"MEJE-KW-005665","row_version":2,"title":"건설·운영 게임","original":"Construction and Management Games","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"자원과 시설을 관리하며 공간이나 조직을 키워 나가는 게임 장르다. 목표가 정해진 경우도 있고 스스로 운영 방식을 찾는 자유로운 놀이도 있다. 시설을 짓고 키우는 과정을 작품의 주된 성취로 보이는 이야기와 연결된다: 짓는 일이 멋진 모험이 되기.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-005665/index.html"},{"id":"MEJE-KW-005666","row_version":2,"title":"건설 노동자의 거리 성희롱을 그리기","original":"Construction Catcalls","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"건설 현장의 노동자가 지나가는 사람에게 성적 말을 던지는 장면을 반복적으로 사용한다. 괴롭힘을 농담으로 처리하거나 특정 직업군에 고정시키는 표현이 될 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005666/index.html"},{"id":"MEJE-KW-005667","row_version":1,"title":"짓는 일이 멋진 모험이 되기","original":"Construction Is Awesome","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"건물을 세우거나 망가진 곳을 복구하는 과정을 이야기의 성취로 그린다. 파괴가 아닌 협력과 축적도 큰 장면의 힘이 된다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-005667/index.html"},{"id":"MEJE-KW-005668","row_version":2,"title":"공사 현장에서 벌이는 대결","original":"Construction Site Fight","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"인물들이 아직 완성되지 않은 건물이나 도로에서 맞선다. 불안정한 지형과 미완성 구조가 장면의 긴장을 키운다. 같은 미완성 건물도 대결이 아닌 연속된 위기와 추격의 무대가 될 수 있다: 공사장의 위험을 넘나드는 소동.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-005668/index.html"},{"id":"MEJE-KW-005669","row_version":2,"title":"건설 장비가 파괴의 도구가 되기","original":"Construction Vehicle Rampage","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"무언가를 짓기 위한 대형 장비가 작품 안에서는 주변을 부수며 위협하는 물건으로 쓰인다. 원래 용도와 반대되는 행동이 장면의 규모를 키운다. 건설 장비를 파괴에 쓰는 장면은 무언가를 짓는 일을 성취로 그리는 관점과 대비된다: 짓는 일이 멋진 모험이 되기.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005669/index.html"},{"id":"MEJE-KW-005670","row_version":1,"title":"공사장의 위험을 넘나드는 소동","original":"Construction Zone Calamity","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 공사 중인 장소에 들어가고 이를 뒤쫓는 사람이 위험을 막으려 애쓴다. 미완성 공간이 연속된 몸개그의 무대가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005670/index.html"},{"id":"MEJE-KW-005671","row_version":1,"title":"공사 현장에 감춰진 시신","original":"Constructive Body Disposal","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"공사 중인 장소에 과거 범죄의 시신이 숨겨진 설정이다. 이후 건축물의 비밀이 드러나면 오래된 사건이 다시 시작된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005671/index.html"},{"id":"MEJE-KW-005672","row_version":1,"title":"고칠 방향을 알려 주는 비평","original":"Constructive Criticism","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품의 장단점을 구체적으로 짚고 개선할 수 있는 방향을 제안한다. 평가가 공격이나 칭찬에 머물지 않고 다음 작업의 재료가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005672/index.html"},{"id":"MEJE-KW-005673","row_version":2,"title":"수감된 범죄자에게 수사 조언을 듣기","original":"Consulting a Convicted Killer","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"수사팀이 새로운 사건을 이해하려고 이미 수감된 범죄자의 관점에 도움을 구한다. 필요한 단서와 위험한 조언 사이에서 신뢰를 가늠해야 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005673/index.html"},{"id":"MEJE-KW-005674","row_version":1,"title":"인형에게 대신 결정을 묻는 인물","original":"Consulting Mister Puppet","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 손인형이나 늘 데리고 다니는 물건에게 의견을 묻고 그 답을 믿는다. 혼자 내리기 어려운 판단을 다른 목소리의 형태로 드러낸다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005674/index.html"},{"id":"MEJE-KW-005675","row_version":1,"title":"당신만 모르는 비밀을 판다는 광고","original":"Consumer Conspiracy","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"광고가 어떤 업계가 감춘 비밀을 알려 준다고 약속하며 상품에 관심을 모은다. 정보를 독점한다는 주장으로 소비자의 불신과 기대를 동시에 자극한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005675/index.html"},{"id":"MEJE-KW-005676","row_version":1,"title":"사랑을 삼킴에 빗대는 공포","original":"Consuming Passion","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"인물의 집착과 소유욕을 상대를 먹어 없애려는 이미지로 표현한다. 친밀함의 욕망이 상대의 경계를 지우는 공포로 바뀐다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-005676/index.html"},{"id":"MEJE-KW-005677","row_version":1,"title":"거짓말에 능숙한 인물","original":"Consummate Liar","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 표정과 말의 흐름을 다루어 거짓을 쉽게 들키지 않는다. 그 재능은 사기나 잠입뿐 아니라 누군가를 지키려는 선택에도 쓰일 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005677/index.html"},{"id":"MEJE-KW-005678","row_version":1,"title":"직업 규범을 철저히 지키는 인물","original":"Consummate Professional","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 맡은 일을 감정과 관계보다 앞세우며 전문성을 유지한다. 신뢰를 얻는 능력이면서 때로는 냉담함의 원인이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005678/index.html"},{"id":"MEJE-KW-005679","row_version":2,"title":"즉석에서 이야기를 잘 만드는 인물","original":"Consummate Storyteller","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 짧은 단서만으로 듣는 사람을 끌어들이는 이야기를 짓는다. 재능이 위로와 오락이 될 수도 있고 속임수가 될 수도 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005679/index.html"},{"id":"MEJE-KW-005680","row_version":1,"title":"초야의 증거를 꾸미기","original":"Consummation Counterfeit","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"혼인 첫날밤의 출혈을 순결의 증거로 요구하는 사회에서 인물이 그 증거를 꾸민다. 잘못된 믿음과 강요가 인물의 안전과 선택을 위협한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005680/index.html"},{"id":"MEJE-KW-005681","row_version":2,"title":"다른 기기로 퍼져 가는 인공지능","original":"Contagious A.I.","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"스스로 판단하는 인공지능이 연결된 기기와 시스템으로 번져 간다. 한 몸에 묶이지 않는 존재가 공간의 통제권을 넓혀 간다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005681/index.html"},{"id":"MEJE-KW-005682","row_version":1,"title":"믿기 어려운 진실이 퍼져 나가기","original":"Contagious Cassandra Truth","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"처음에는 아무도 믿지 않던 경고를 한 사람이 받아들이고 다시 다른 사람에게 전한다. 신뢰의 연결이 진실을 고립된 주장 밖으로 꺼낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005682/index.html"},{"id":"MEJE-KW-005683","row_version":2,"title":"영웅에게 감화되는 반영웅·악역","original":"Contagious Heroism","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"반영웅이나 악역이 영웅과 함께 지내며 점차 남을 돕는 선택을 하게 되는 인물 변화. 영웅성이 관계를 통해 전해지는 구조다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005683/index.html"},{"id":"MEJE-KW-005684","row_version":1,"title":"옆 사람에게 옮아가는 웃음","original":"Contagious Laughter","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"한 사람의 웃음이 주변 사람에게 차례로 번진다. 웃는 이유보다 함께 웃게 되는 분위기가 장면을 움직인다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-005684/index.html"},{"id":"MEJE-KW-005685","row_version":2,"title":"주변 인물이 이어받는 능력","original":"Contagious Powers","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"영웅과 가까운 조력자나 연인이 별도의 능력을 영구적으로 얻어 역할이 커지는 전개. 힘이 전염되는 듯 보이지만 반드시 접촉하거나 같은 능력을 얻는 것은 아니다. 능력이 주변 사람에게 퍼질 때 그 영향이 위험하다면 착용자가 특별한 옷을 입어야 할 수도 있다: 위험한 힘을 억누르는 옷.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005685/index.html"},{"id":"MEJE-KW-005686","row_version":1,"title":"상자 안쪽에 붙어 숨기","original":"Container Cling","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"숨은 인물이 상자가 들리면 보일 것 같지만 안쪽에 붙어 함께 움직여 발견되지 않는다. 관객의 예상과 화면의 실제 위치가 엇갈린다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005686/index.html"},{"id":"MEJE-KW-005687","row_version":1,"title":"컨테이너가 만든 미로","original":"Container Maze","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"항구의 화물 상자가 빽빽하게 쌓여 길과 시야를 가린다. 닮은 통로가 추격과 수색의 긴장을 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-005687/index.html"},{"id":"MEJE-KW-005688","row_version":2,"title":"위험한 힘을 억누르는 옷","original":"Containment Clothing","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 자신의 힘이 주변에 미치지 않도록 특별한 옷을 입는다. 의상이 방어구보다 능력을 제어하는 경계가 된다. 사람이 입는 옷 대신 위험한 힘이 있는 공간 전체에 장벽을 두는 방식도 있다: 위험한 힘을 가두는 장.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005688/index.html"},{"id":"MEJE-KW-005689","row_version":2,"title":"위험한 힘을 가두는 장","original":"Containment Field","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"불안정한 에너지나 존재를 보이지 않는 장벽 안에 가둔다. 장벽이 약해질수록 세계의 안전이 흔들린다. 장치가 만드는 장벽과 달리 인물 자신의 힘으로 폭발을 한곳에 묶는 장면도 있다: 폭발을 손안에 가두는 힘.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005689/index.html"},{"id":"MEJE-KW-005690","row_version":1,"title":"폭발을 손안에 가두는 힘","original":"Contain the Kaboom","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 큰 폭발의 범위를 한곳에 묶어 주변의 피해를 막는다. 파괴력의 크기를 역으로 인물의 제어 능력을 보여 주는 데 쓴다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005690/index.html"}]}.cards;